#include <stdlib.h>
#include <string.h>
#ifdef _OPENMP
#include <omp.h>
#endif

#ifdef __AVX512F__
#define VW 16
#define MR 12
#else
#define VW 8
#define MR 6
#endif
#define NR (2 * VW)
#define KC 256

typedef float vf __attribute__((vector_size(VW * 4), aligned(VW * 4)));
typedef float vfu __attribute__((vector_size(VW * 4), aligned(4)));

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int accum, int mr, int nr)
{
    vf acc[MR][2];
#pragma GCC unroll 16
    for (int r = 0; r < MR; r++) {
        acc[r][0] = (vf){0};
        acc[r][1] = (vf){0};
    }

    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(b + k * NR);
        vf b1 = *(const vf *)(b + k * NR + VW);
        const float *ak = a + k * MR;
#pragma GCC unroll 16
        for (int r = 0; r < MR; r++) {
            float ar = ak[r];
            acc[r][0] += ar * b0;
            acc[r][1] += ar * b1;
        }
    }

    if (mr == MR && nr == NR) {
#pragma GCC unroll 16
        for (int r = 0; r < MR; r++) {
            vfu *p0 = (vfu *)(c + (size_t)r * ldc);
            vfu *p1 = (vfu *)(c + (size_t)r * ldc + VW);
            if (accum) {
                *p0 += acc[r][0];
                *p1 += acc[r][1];
            } else {
                *p0 = acc[r][0];
                *p1 = acc[r][1];
            }
        }
    } else {
        float tmp[MR * NR] __attribute__((aligned(64)));
        for (int r = 0; r < MR; r++) {
            *(vf *)(tmp + r * NR) = acc[r][0];
            *(vf *)(tmp + r * NR + VW) = acc[r][1];
        }
        for (int r = 0; r < mr; r++) {
            float *cr = c + (size_t)r * ldc;
            if (accum)
                for (int j = 0; j < nr; j++) cr[j] += tmp[r * NR + j];
            else
                for (int j = 0; j < nr; j++) cr[j] = tmp[r * NR + j];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int mp = (n + MR - 1) / MR;
    int np = (n + NR - 1) / NR;
    int nkb = (n + KC - 1) / KC;
    size_t Mpad = (size_t)mp * MR;
    size_t Npad = (size_t)np * NR;

    size_t asz = (Mpad * n * sizeof(float) + 63) & ~(size_t)63;
    size_t bsz = (Npad * n * sizeof(float) + 63) & ~(size_t)63;
    float *Ap = (float *)aligned_alloc(64, asz);
    float *Bp = (float *)aligned_alloc(64, bsz);

    int nt = 1;
#ifdef _OPENMP
    nt = omp_get_max_threads();
#endif

    int MCP = 120 / MR, NCP = 256 / NR;
    if (MCP > mp) MCP = mp;
    if (NCP > np) NCP = np;
    int nmt = (mp + MCP - 1) / MCP, nnt = (np + NCP - 1) / NCP;
    while (nmt * nnt < 3 * nt && NCP > 1) {
        NCP--;
        nnt = (np + NCP - 1) / NCP;
    }
    while (nmt * nnt < 3 * nt && MCP > 1) {
        MCP--;
        nmt = (mp + MCP - 1) / MCP;
    }
    int nitems = nmt * nnt;

#pragma omp parallel
    {
        /* Pack A: block p, panel ip -> kc x MR, zero-padded rows */
#pragma omp for schedule(static) nowait
        for (int t = 0; t < nkb * mp; t++) {
            int pb = t / mp, ip = t % mp;
            int p0 = pb * KC;
            int kc = n - p0 < KC ? n - p0 : KC;
            float *dst = Ap + (size_t)p0 * Mpad + (size_t)ip * MR * kc;
            int i0 = ip * MR;
            for (int r = 0; r < MR; r++) {
                int i = i0 + r;
                if (i < n) {
                    const float *src = A + (size_t)i * n + p0;
                    for (int k = 0; k < kc; k++) dst[k * MR + r] = src[k];
                } else {
                    for (int k = 0; k < kc; k++) dst[k * MR + r] = 0.0f;
                }
            }
        }

        /* Pack B: block p, panel jp -> kc x NR, zero-padded columns */
#pragma omp for schedule(static)
        for (int t = 0; t < nkb * np; t++) {
            int pb = t / np, jp = t % np;
            int p0 = pb * KC;
            int kc = n - p0 < KC ? n - p0 : KC;
            float *dst = Bp + (size_t)p0 * Npad + (size_t)jp * NR * kc;
            int j0 = jp * NR;
            int w = n - j0 < NR ? n - j0 : NR;
            for (int k = 0; k < kc; k++) {
                const float *src = B + (size_t)(p0 + k) * n + j0;
                float *d = dst + k * NR;
                if (w == NR) {
                    memcpy(d, src, NR * sizeof(float));
                } else {
                    for (int j = 0; j < w; j++) d[j] = src[j];
                    for (int j = w; j < NR; j++) d[j] = 0.0f;
                }
            }
        }

        /* Compute: items are MC x NCG tiles of C over full K */
#pragma omp for schedule(dynamic, 1)
        for (int it = 0; it < nitems; it++) {
            int mt = it / nnt, ntile = it % nnt;
            int ip0 = mt * MCP, ip1 = ip0 + MCP < mp ? ip0 + MCP : mp;
            int jp0 = ntile * NCP, jp1 = jp0 + NCP < np ? jp0 + NCP : np;
            for (int pb = 0; pb < nkb; pb++) {
                int p0 = pb * KC;
                int kc = n - p0 < KC ? n - p0 : KC;
                const float *Ab = Ap + (size_t)p0 * Mpad;
                const float *Bb = Bp + (size_t)p0 * Npad;
                for (int jp = jp0; jp < jp1; jp++) {
                    const float *bpan = Bb + (size_t)jp * NR * kc;
                    int j0 = jp * NR;
                    int nr = n - j0 < NR ? n - j0 : NR;
                    for (int ip = ip0; ip < ip1; ip++) {
                        const float *apan = Ab + (size_t)ip * MR * kc;
                        int i0 = ip * MR;
                        int mr = n - i0 < MR ? n - i0 : MR;
                        kernel(kc, apan, bpan, C + (size_t)i0 * n + j0, n,
                               pb > 0, mr, nr);
                    }
                }
            }
        }
    }

    free(Ap);
    free(Bp);
}
